#!/bin/bash\n\n# Monitoring Setup Script for AgentScan\n# Sets up Prometheus, Grafana, and Alertmanager for comprehensive monitoring\n\nset -euo pipefail\n\n# Script configuration\nSCRIPT_DIR=\"$(cd \"$(dirname \"${BASH_SOURCE[0]}\")\" && pwd)\"\nPROJECT_ROOT=\"$(dirname \"$(dirname \"$SCRIPT_DIR\")\")\"  # Go up two levels\nDEPLOYMENT_DIR=\"$PROJECT_ROOT/deployment\"\nMONITORING_DIR=\"$DEPLOYMENT_DIR/monitoring\"\n\n# Default configuration\nENVIRONMENT=\"production\"\nNAMESPACE=\"agentscan-monitoring\"\nDRY_RUN=false\nVERBOSE=false\nSKIP_GRAFANA=false\nSKIP_ALERTMANAGER=false\n\n# Colors for output\nRED='\\033[0;31m'\nGREEN='\\033[0;32m'\nYELLOW='\\033[1;33m'\nBLUE='\\033[0;34m'\nNC='\\033[0m' # No Color\n\n# Logging functions\nlog_info() {\n    echo -e \"${BLUE}[INFO]${NC} $1\"\n}\n\nlog_success() {\n    echo -e \"${GREEN}[SUCCESS]${NC} $1\"\n}\n\nlog_warning() {\n    echo -e \"${YELLOW}[WARNING]${NC} $1\"\n}\n\nlog_error() {\n    echo -e \"${RED}[ERROR]${NC} $1\"\n}\n\nlog_verbose() {\n    if [[ \"$VERBOSE\" == \"true\" ]]; then\n        echo -e \"${BLUE}[VERBOSE]${NC} $1\"\n    fi\n}\n\n# Function to show help\nshow_help() {\n    cat << EOF\nAgentScan Monitoring Setup Script\n\nUsage: $0 [OPTIONS]\n\nOptions:\n    --environment ENV       Environment (default: production)\n    --namespace NS          Kubernetes namespace (default: agentscan-monitoring)\n    --dry-run              Show what would be done without making changes\n    --verbose              Enable verbose logging\n    --skip-grafana         Skip Grafana installation\n    --skip-alertmanager    Skip Alertmanager installation\n    --help                 Show this help message\n\nExamples:\n    $0 --environment staging --verbose\n    $0 --dry-run --skip-grafana\n    $0 --namespace monitoring\n\nEOF\n}\n\n# Function to check prerequisites\ncheck_prerequisites() {\n    log_info \"Checking prerequisites...\"\n    \n    local missing_tools=()\n    \n    # Check required tools\n    local required_tools=(\"kubectl\" \"helm\")\n    for tool in \"${required_tools[@]}\"; do\n        if ! command -v \"$tool\" &> /dev/null; then\n            missing_tools+=(\"$tool\")\n        fi\n    done\n    \n    if [[ ${#missing_tools[@]} -gt 0 ]]; then\n        log_error \"Missing required tools: ${missing_tools[*]}\"\n        return 1\n    fi\n    \n    # Check kubectl connection\n    if ! kubectl cluster-info &> /dev/null; then\n        log_error \"kubectl is not connected to a cluster\"\n        return 1\n    fi\n    \n    # Check if Helm is initialized\n    if ! helm version &> /dev/null; then\n        log_error \"Helm is not properly initialized\"\n        return 1\n    fi\n    \n    log_success \"Prerequisites check passed\"\n    return 0\n}\n\n# Function to create namespace\ncreate_namespace() {\n    log_info \"Creating monitoring namespace: $NAMESPACE\"\n    \n    if [[ \"$DRY_RUN\" == \"true\" ]]; then\n        log_warning \"DRY RUN: Would create namespace $NAMESPACE\"\n        return 0\n    fi\n    \n    # Create namespace if it doesn't exist\n    if ! kubectl get namespace \"$NAMESPACE\" &> /dev/null; then\n        kubectl create namespace \"$NAMESPACE\"\n        log_success \"Created namespace: $NAMESPACE\"\n    else\n        log_verbose \"Namespace already exists: $NAMESPACE\"\n    fi\n    \n    # Label namespace for monitoring\n    kubectl label namespace \"$NAMESPACE\" monitoring=enabled --overwrite\n    \n    return 0\n}\n\n# Function to add Helm repositories\nadd_helm_repos() {\n    log_info \"Adding Helm repositories...\"\n    \n    if [[ \"$DRY_RUN\" == \"true\" ]]; then\n        log_warning \"DRY RUN: Would add Helm repositories\"\n        return 0\n    fi\n    \n    # Add Prometheus community repo\n    helm repo add prometheus-community https://prometheus-community.github.io/helm-charts\n    \n    # Add Grafana repo\n    helm repo add grafana https://grafana.github.io/helm-charts\n    \n    # Update repos\n    helm repo update\n    \n    log_success \"Helm repositories added and updated\"\n    return 0\n}\n\n# Function to install Prometheus\ninstall_prometheus() {\n    log_info \"Installing Prometheus...\"\n    \n    if [[ \"$DRY_RUN\" == \"true\" ]]; then\n        log_warning \"DRY RUN: Would install Prometheus\"\n        return 0\n    fi\n    \n    # Create Prometheus values file\n    local values_file=\"$MONITORING_DIR/prometheus-values.yaml\"\n    \n    cat > \"$values_file\" << EOF\n# Prometheus Helm Chart Values\nprometheus:\n  prometheusSpec:\n    retention: 30d\n    retentionSize: 10GB\n    storageSpec:\n      volumeClaimTemplate:\n        spec:\n          storageClassName: fast-ssd\n          accessModes: [\"ReadWriteOnce\"]\n          resources:\n            requests:\n              storage: 20Gi\n    \n    # Resource limits\n    resources:\n      limits:\n        cpu: 2000m\n        memory: 4Gi\n      requests:\n        cpu: 1000m\n        memory: 2Gi\n    \n    # Additional scrape configs\n    additionalScrapeConfigs:\n      - job_name: 'agentscan-api'\n        static_configs:\n          - targets: ['agentscan-api.agentscan.svc.cluster.local:8080']\n        metrics_path: '/metrics'\n        scrape_interval: 30s\n      \n      - job_name: 'agentscan-orchestrator'\n        static_configs:\n          - targets: ['agentscan-orchestrator.agentscan.svc.cluster.local:8081']\n        metrics_path: '/metrics'\n        scrape_interval: 30s\n\n# Alertmanager configuration\nalertmanager:\n  alertmanagerSpec:\n    storage:\n      volumeClaimTemplate:\n        spec:\n          storageClassName: fast-ssd\n          accessModes: [\"ReadWriteOnce\"]\n          resources:\n            requests:\n              storage: 5Gi\n    \n    resources:\n      limits:\n        cpu: 500m\n        memory: 1Gi\n      requests:\n        cpu: 100m\n        memory: 256Mi\n\n# Grafana configuration\ngrafana:\n  enabled: true\n  adminPassword: \"${GRAFANA_ADMIN_PASSWORD:-admin123}\"\n  \n  persistence:\n    enabled: true\n    storageClassName: fast-ssd\n    size: 5Gi\n  \n  resources:\n    limits:\n      cpu: 500m\n      memory: 1Gi\n    requests:\n      cpu: 100m\n      memory: 256Mi\n  \n  # Grafana configuration\n  grafana.ini:\n    server:\n      root_url: \"https://grafana.agentscan.dev\"\n    security:\n      admin_user: admin\n      admin_password: \"${GRAFANA_ADMIN_PASSWORD:-admin123}\"\n    auth:\n      disable_login_form: false\n    \n  # Data sources\n  datasources:\n    datasources.yaml:\n      apiVersion: 1\n      datasources:\n        - name: Prometheus\n          type: prometheus\n          url: http://prometheus-server:80\n          access: proxy\n          isDefault: true\n\n# Node exporter\nnodeExporter:\n  enabled: true\n\n# Kube state metrics\nkubeStateMetrics:\n  enabled: true\nEOF\n    \n    # Install Prometheus stack\n    helm upgrade --install prometheus-stack prometheus-community/kube-prometheus-stack \\\n        --namespace \"$NAMESPACE\" \\\n        --values \"$values_file\" \\\n        --wait \\\n        --timeout 10m\n    \n    log_success \"Prometheus installed successfully\"\n    return 0\n}\n\n# Function to configure Prometheus rules\nconfigure_prometheus_rules() {\n    log_info \"Configuring Prometheus alert rules...\"\n    \n    if [[ \"$DRY_RUN\" == \"true\" ]]; then\n        log_warning \"DRY RUN: Would configure Prometheus rules\"\n        return 0\n    fi\n    \n    # Apply custom alert rules\n    kubectl apply -f \"$MONITORING_DIR/alert-rules.yml\" -n \"$NAMESPACE\"\n    \n    log_success \"Prometheus rules configured\"\n    return 0\n}\n\n# Function to install Grafana dashboards\ninstall_grafana_dashboards() {\n    if [[ \"$SKIP_GRAFANA\" == \"true\" ]]; then\n        log_info \"Skipping Grafana dashboard installation\"\n        return 0\n    fi\n    \n    log_info \"Installing Grafana dashboards...\"\n    \n    if [[ \"$DRY_RUN\" == \"true\" ]]; then\n        log_warning \"DRY RUN: Would install Grafana dashboards\"\n        return 0\n    fi\n    \n    # Create dashboard ConfigMaps\n    local dashboard_dir=\"$MONITORING_DIR/dashboards\"\n    \n    if [[ -d \"$dashboard_dir\" ]]; then\n        for dashboard in \"$dashboard_dir\"/*.json; do\n            if [[ -f \"$dashboard\" ]]; then\n                local dashboard_name=$(basename \"$dashboard\" .json)\n                kubectl create configmap \"grafana-dashboard-$dashboard_name\" \\\n                    --from-file=\"$dashboard\" \\\n                    -n \"$NAMESPACE\" \\\n                    --dry-run=client -o yaml | kubectl apply -f -\n                \n                # Label for Grafana to pick up\n                kubectl label configmap \"grafana-dashboard-$dashboard_name\" \\\n                    grafana_dashboard=1 -n \"$NAMESPACE\" --overwrite\n                \n                log_verbose \"Installed dashboard: $dashboard_name\"\n            fi\n        done\n    fi\n    \n    log_success \"Grafana dashboards installed\"\n    return 0\n}\n\n# Function to configure Alertmanager\nconfigure_alertmanager() {\n    if [[ \"$SKIP_ALERTMANAGER\" == \"true\" ]]; then\n        log_info \"Skipping Alertmanager configuration\"\n        return 0\n    fi\n    \n    log_info \"Configuring Alertmanager...\"\n    \n    if [[ \"$DRY_RUN\" == \"true\" ]]; then\n        log_warning \"DRY RUN: Would configure Alertmanager\"\n        return 0\n    fi\n    \n    # Create Alertmanager configuration\n    local alertmanager_config=\"$MONITORING_DIR/alertmanager-config.yml\"\n    \n    cat > \"$alertmanager_config\" << EOF\nglobal:\n  smtp_smarthost: '${SMTP_HOST:-localhost:587}'\n  smtp_from: 'alerts@agentscan.dev'\n  smtp_auth_username: '${SMTP_USER:-}'\n  smtp_auth_password: '${SMTP_PASSWORD:-}'\n\nroute:\n  group_by: ['alertname', 'cluster', 'service']\n  group_wait: 10s\n  group_interval: 10s\n  repeat_interval: 1h\n  receiver: 'default'\n  routes:\n    - match:\n        severity: critical\n      receiver: 'critical-alerts'\n    - match:\n        severity: warning\n      receiver: 'warning-alerts'\n\nreceivers:\n  - name: 'default'\n    email_configs:\n      - to: 'team@agentscan.dev'\n        subject: 'AgentScan Alert: {{ .GroupLabels.alertname }}'\n        body: |\n          {{ range .Alerts }}\n          Alert: {{ .Annotations.summary }}\n          Description: {{ .Annotations.description }}\n          Labels: {{ range .Labels.SortedPairs }}{{ .Name }}={{ .Value }} {{ end }}\n          {{ end }}\n  \n  - name: 'critical-alerts'\n    email_configs:\n      - to: 'oncall@agentscan.dev'\n        subject: '🚨 CRITICAL: {{ .GroupLabels.alertname }}'\n        body: |\n          CRITICAL ALERT TRIGGERED\n          \n          {{ range .Alerts }}\n          Alert: {{ .Annotations.summary }}\n          Description: {{ .Annotations.description }}\n          Runbook: {{ .Annotations.runbook_url }}\n          Labels: {{ range .Labels.SortedPairs }}{{ .Name }}={{ .Value }} {{ end }}\n          {{ end }}\n    \n    slack_configs:\n      - api_url: '${SLACK_WEBHOOK_URL:-}'\n        channel: '#alerts'\n        title: '🚨 Critical Alert: {{ .GroupLabels.alertname }}'\n        text: '{{ range .Alerts }}{{ .Annotations.summary }}{{ end }}'\n  \n  - name: 'warning-alerts'\n    email_configs:\n      - to: 'team@agentscan.dev'\n        subject: '⚠️ WARNING: {{ .GroupLabels.alertname }}'\n        body: |\n          {{ range .Alerts }}\n          Alert: {{ .Annotations.summary }}\n          Description: {{ .Annotations.description }}\n          Labels: {{ range .Labels.SortedPairs }}{{ .Name }}={{ .Value }} {{ end }}\n          {{ end }}\nEOF\n    \n    # Create secret for Alertmanager config\n    kubectl create secret generic alertmanager-config \\\n        --from-file=alertmanager.yml=\"$alertmanager_config\" \\\n        -n \"$NAMESPACE\" \\\n        --dry-run=client -o yaml | kubectl apply -f -\n    \n    log_success \"Alertmanager configured\"\n    return 0\n}\n\n# Function to setup ingress\nsetup_ingress() {\n    log_info \"Setting up ingress for monitoring services...\"\n    \n    if [[ \"$DRY_RUN\" == \"true\" ]]; then\n        log_warning \"DRY RUN: Would setup ingress\"\n        return 0\n    fi\n    \n    # Create ingress for Grafana\n    cat << EOF | kubectl apply -f -\napiVersion: networking.k8s.io/v1\nkind: Ingress\nmetadata:\n  name: monitoring-ingress\n  namespace: $NAMESPACE\n  annotations:\n    kubernetes.io/ingress.class: nginx\n    cert-manager.io/cluster-issuer: letsencrypt-prod\n    nginx.ingress.kubernetes.io/ssl-redirect: \"true\"\nspec:\n  tls:\n    - hosts:\n        - grafana.agentscan.dev\n        - prometheus.agentscan.dev\n        - alertmanager.agentscan.dev\n      secretName: monitoring-tls\n  rules:\n    - host: grafana.agentscan.dev\n      http:\n        paths:\n          - path: /\n            pathType: Prefix\n            backend:\n              service:\n                name: prometheus-stack-grafana\n                port:\n                  number: 80\n    - host: prometheus.agentscan.dev\n      http:\n        paths:\n          - path: /\n            pathType: Prefix\n            backend:\n              service:\n                name: prometheus-stack-prometheus\n                port:\n                  number: 9090\n    - host: alertmanager.agentscan.dev\n      http:\n        paths:\n          - path: /\n            pathType: Prefix\n            backend:\n              service:\n                name: prometheus-stack-alertmanager\n                port:\n                  number: 9093\nEOF\n    \n    log_success \"Ingress configured\"\n    return 0\n}\n\n# Function to verify installation\nverify_installation() {\n    log_info \"Verifying monitoring installation...\"\n    \n    if [[ \"$DRY_RUN\" == \"true\" ]]; then\n        log_warning \"DRY RUN: Would verify installation\"\n        return 0\n    fi\n    \n    # Wait for pods to be ready\n    log_info \"Waiting for pods to be ready...\"\n    kubectl wait --for=condition=ready pod -l app.kubernetes.io/name=prometheus -n \"$NAMESPACE\" --timeout=300s\n    \n    if [[ \"$SKIP_GRAFANA\" != \"true\" ]]; then\n        kubectl wait --for=condition=ready pod -l app.kubernetes.io/name=grafana -n \"$NAMESPACE\" --timeout=300s\n    fi\n    \n    if [[ \"$SKIP_ALERTMANAGER\" != \"true\" ]]; then\n        kubectl wait --for=condition=ready pod -l app.kubernetes.io/name=alertmanager -n \"$NAMESPACE\" --timeout=300s\n    fi\n    \n    # Check service endpoints\n    log_info \"Checking service endpoints...\"\n    kubectl get services -n \"$NAMESPACE\"\n    \n    log_success \"Monitoring installation verified\"\n    return 0\n}\n\n# Function to print access information\nprint_access_info() {\n    log_info \"Monitoring Access Information\"\n    echo \"=============================\"\n    echo \"\"\n    \n    if [[ \"$DRY_RUN\" != \"true\" ]]; then\n        echo \"Grafana:\"\n        echo \"  URL: https://grafana.agentscan.dev\"\n        echo \"  Username: admin\"\n        echo \"  Password: ${GRAFANA_ADMIN_PASSWORD:-admin123}\"\n        echo \"\"\n        \n        echo \"Prometheus:\"\n        echo \"  URL: https://prometheus.agentscan.dev\"\n        echo \"\"\n        \n        echo \"Alertmanager:\"\n        echo \"  URL: https://alertmanager.agentscan.dev\"\n        echo \"\"\n        \n        echo \"Port Forwarding (alternative access):\"\n        echo \"  Grafana: kubectl port-forward -n $NAMESPACE svc/prometheus-stack-grafana 3000:80\"\n        echo \"  Prometheus: kubectl port-forward -n $NAMESPACE svc/prometheus-stack-prometheus 9090:9090\"\n        echo \"  Alertmanager: kubectl port-forward -n $NAMESPACE svc/prometheus-stack-alertmanager 9093:9093\"\n    else\n        echo \"DRY RUN: Access information would be displayed here\"\n    fi\n    \n    echo \"\"\n}\n\n# Main function\nmain() {\n    log_info \"Starting monitoring setup for environment: $ENVIRONMENT\"\n    \n    # Check prerequisites\n    if ! check_prerequisites; then\n        exit 1\n    fi\n    \n    # Create namespace\n    create_namespace\n    \n    # Add Helm repositories\n    add_helm_repos\n    \n    # Install Prometheus\n    install_prometheus\n    \n    # Configure Prometheus rules\n    configure_prometheus_rules\n    \n    # Install Grafana dashboards\n    install_grafana_dashboards\n    \n    # Configure Alertmanager\n    configure_alertmanager\n    \n    # Setup ingress\n    setup_ingress\n    \n    # Verify installation\n    verify_installation\n    \n    # Print access information\n    print_access_info\n    \n    log_success \"Monitoring setup completed successfully!\"\n}\n\n# Parse command line arguments\nwhile [[ $# -gt 0 ]]; do\n    case $1 in\n        --environment)\n            ENVIRONMENT=\"$2\"\n            shift 2\n            ;;\n        --namespace)\n            NAMESPACE=\"$2\"\n            shift 2\n            ;;\n        --dry-run)\n            DRY_RUN=true\n            shift\n            ;;\n        --verbose)\n            VERBOSE=true\n            shift\n            ;;\n        --skip-grafana)\n            SKIP_GRAFANA=true\n            shift\n            ;;\n        --skip-alertmanager)\n            SKIP_ALERTMANAGER=true\n            shift\n            ;;\n        --help|-h)\n            show_help\n            exit 0\n            ;;\n        *)\n            log_error \"Unknown option: $1\"\n            show_help\n            exit 1\n            ;;\n    esac\ndone\n\n# Make script executable\nchmod +x \"$0\"\n\n# Run main function\nmain\n"